Method.Implementation:
$$$TRACE("Inside "_..%ConfigName_" Method SelectTacticalDbResultsJdbciActivityRequest")

set pResponse = ##class(EnsLib.SQL.Snapshot).%New()

set tSQL ="SELECT r. SERVICE_EVENT_EXTERNAL_ID , r.EXAM_CODE_NCID, se.REPRESENTATION_TXT, se.NCID, se.NULL_VALUE_REASON_NCID, se.NULL_VALUE_REASON_TXT, sev.VALUE_STR, sev.VALUE_NUM, sev.VALUE_DTS, sev.UNIT_OF_MEASUREMENT, sev.UNIT_OF_MEASUREMENT_NCID, sev.VALUE_NCID, to_char(CAST((FROM_TZ(CAST(r.EXAM_COMPLETED_TIME AS TIMESTAMP),'+00:00') AT TIME ZONE 'US/Mountain') as date), 'YYYYMMDDHHMISS') FROM SPM.REPORT r JOIN SPM.SYNOPTIC_ELEMENT se ON (r.ID = se.REPORT_ID) LEFT JOIN SPM.SYNOPTIC_ELEMENT_VALUE sev ON (se.ID = sev.SYNOPTIC_ELEMENT_ID) WHERE (r.SERVICE_EVENT_EXTERNAL_ID ='"_pRequest.ACCESSIONNO_"' AND r.IS_TEST = 0)"

set tSC = ..Adapter.ExecuteQuery(.pResponse,tSQL)

if tSC = 1{
	$$$TRACE("Successfully executed Query:"_tSQL)
	set rowCount = pResponse.RowCount
	$$$TRACE("Row Count:"_rowCount)
	}else{
	$$$TRACE("Failed to execute Query:"_tSQL)	
}

Quit tSC
